mapper.select:


    inner join sys_user u on u.user_name = tstockdetail.create_by and u.status = '0'
    inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'


    tstockdetail.del_flag = '0'
     and tstockdetail.location_id = #{locationId}
     and tstockdetail.material_id = #{materialId}
     and tstockdetail.before_count = #{beforeCount}
     and tstockdetail.current_count = #{currentCount}
     and tstockdetail.type = #{type}
     and tstockdetail.origin_id = #{originId}
     and tstockdetail.origin_code like concat('%', #{originCode}, '%')
     and tstockdetail.status = #{status}


${params.dataScope}

select current_count
from t_stock_detail
where del_flag = '0'
 and location_id = #{locationId}
 and material_id = #{materialId}
 and batch_code = #{batchCode}
order by id desc
limit 1

select sd.batch_code batchCode, sd.type, ABS(sd.current_count-sd.before_count) count, sd.create_time createTime, m.code materialCode, m.name materialName, u.name unitName, cu.name contactsUnitName from t_stock_detail sd LEFT JOIN t_material m on m.id=sd.material_id LEFT JOIN t_unit u on u.id=m.unit_id LEFT JOIN t_contacts_unit cu on cu.id=m.contacts_unit_id
inner join sys_user us on us.user_name = sd.create_by and us.status = '0' inner join sys_dept d on u.dept_id = d.dept_id and d.status = '0'
where sd.del_flag = '0'
and sd.type=#{type}
and sd.type in('1','2')
and m.code like concat('%', #{materialCode}, '%') and m.name like concat('%', #{materialName}, '%') and cu.id=#{contactsUnitId}
and sd.create_time between #{beginDate} and #{endDate}
${params.dataScope} order by sd.create_time desc
